sys_script_include.script:
var AuthorizationService = Class.create();
AuthorizationService.prototype = {
    initialize: function() {},

    canApproveItem: function(itemSysId, userId) {
        if (!itemSysId || !userId) return { authorized: false, reason: 'Missing item or user' };

        var ci = new GlideRecord('x_2316178_contin_0_cont_item');
        if (!ci.get(itemSysId)) return { authorized: false, reason: 'Continuity Item not found' };

        var responsibleMgr = ci.getValue('responsible_manager');
        if (!responsibleMgr) return { authorized: false, reason: 'No responsible manager assigned' };

        if (responsibleMgr != userId) {
            return { authorized: false, reason: 'User is not the responsible manager for this item' };
        }

        // Check item is in pending state
        if (ci.getValue('decision_state') != 'pending') {
            return { authorized: false, reason: 'Item is not in pending state' };
        }

        return { authorized: true, reason: 'User is the responsible manager' };
    },

    canExecuteItem: function(itemSysId, userId) {
        if (!itemSysId || !userId) return { authorized: false, reason: 'Missing item or user' };

        var ci = new GlideRecord('x_2316178_contin_0_cont_item');
        if (!ci.get(itemSysId)) return { authorized: false, reason: 'Continuity Item not found' };

        if (ci.getValue('decision_state') != 'approved') {
            return { authorized: false, reason: 'Item is not approved' };
        }

        // Check user has operator role
        var gr = new GlideRecord('sys_user_has_role');
        gr.addQuery('user', userId);
        gr.addQuery('role.name', 'x_2316178_contin_0.continuity_operator');
        gr.query();
        if (!gr.next()) {
            // Also check inherited roles
            if (!gs.hasRole('x_2316178_contin_0.continuity_operator')) {
                return { authorized: false, reason: 'User does not have operator role' };
            }
        }

        return { authorized: true, reason: 'User is authorized to execute' };
    },

    logDenial: function(action, userId, reason) {
        gs.info('Authorization denied: action=' + action + ', user=' + userId + ', reason=' + reason);
    },

    type: 'AuthorizationService'
};
